// ID selection (fastest)
const el = document.getElementById('header');
// CSS selector (flexible)
const firstDiv = document.querySelector('div');

const newDiv = document.createElement('div');
newDiv.textContent = 'Hello DOM!';
document.body.appendChild(newDiv);
// Using insertAdjacentHTML
document.body.insertAdjacentHTML('beforeend', '<p>Fast insertion</p>');

document.getElementById('list').addEventListener('click', (e) => {
  if(e.target.matches('li')) console.log('List item clicked!');
  if(e.target.closest('.btn')) handleButton(e.target);
});

// Inline styles
element.style.backgroundColor = 'red';
// CSS class toggle
element.classList.toggle('active');

document.addEventListener('keydown', (e) => {
  if(e.key === 'Escape') closeModal();
  if(e.ctrlKey && e.key === 's') saveForm();
});

const event = new CustomEvent('itemAdded', {
  detail: { productId: 456 }
});
document.dispatchEvent(event);

const observer = new MutationObserver((mutations) => {
  mutations.forEach(mutation => {
    if(mutation.type === 'childList') console.log('DOM changed!');
  });
});
observer.observe(document.body, { childList: true });

// Batch DOM changes
const fragment = document.createDocumentFragment();
items.forEach(item => {
  const li = document.createElement('li');
  li.textContent = item;
  fragment.appendChild(li);
});
listEl.appendChild(fragment);

